from networkx import Graph
import networkx as nx

G = nx.Graph()
for i in range(27):
    G.add_node(i)

# Add edges to ensure every vertex has degree between 5 and 7
for i in range(27):
    for j in range(i+1, 27):
        if len(list(G.neighbors(i))) < 5 and len(list(G.neighbors(j))) < 5:
            G.add_edge(i, j)

# Check if the girth (shortest cycle) is at least 7
if nx.girth(G) >= 7:
    print("SATISFIABLE")
    print(list(G.edges))
else:
    print("UNSATISFIABLE")
